from typeguard import typechecked
from typing import Any

@typechecked
def create_local_class_instance_with_typechecked() -> Any:
    class Inner:
        def __init__(self):
            self.value = "test"

    return Inner()

instance = create_local_class_instance_with_typechecked()
print("with decorator:", instance.value)

@typechecked
def create_local_class_with_annotations():
    class Inner:
        value: str

        def __init__(self, value: str) -> None:
            self.value = value

    return Inner("test")

instance = create_local_class_with_annotations()
print("with annotations:", instance.value)

@typechecked
def create_nested():
    class Inner:
        class Nested:
            def __init__(self):
                self.value = "nested"
        def __init__(self):
            self.n = self.Nested()
    return Inner()

instance = create_nested()
print("nested:", instance.n.value)
EOF
